class Solution {
public:
    vector<int> twoSum(vector<int> &nums, int target) {
        vector<int> res;
        unordered_map<int, int> hash;
        for (int i = 0; i < nums.size(); i++) {
            int tmp = target - nums[i];
            if (hash.count(tmp)) {
                res.push_back(i);
                res.push_back(hash[tmp]);
                return res;
            }
            hash[nums[i]] = i;
        }
        return res;
    }
};

