#define MAX_STATES 200005

static int nxt[MAX_STATES][26];
static int link_st[MAX_STATES];
static int len_st[MAX_STATES];

#include <stdlib.h>
#include <string.h>

/*
 * Maximum states in a Suffix Automaton for a string of length N is 2N - 1.
 * Setting MAX_STATES = 200005 accommodates strings up to N = 100,000.
 * Static file-scope allocation places these arrays in the ELF .bss segment.
 */
#define MAX_STATES 200005

static int nxt[MAX_STATES][26];
static int link_st[MAX_STATES];
static int len_st[MAX_STATES];

char* longestDupSubstring(char* s) {
    int n = (int)strlen(s);

    /* Initialize Root State (State 1); State 0 serves as the null sentinel */
    int sz = 1, last = 1;
    len_st[1] = 0;
    link_st[1] = 0;
    memset(nxt[1], 0, sizeof(nxt[1]));

    int max_len = 0, best_end = 0;

    /* Online Suffix Automaton construction: O(N) amortized time */
    for (int i = 0; i < n; ++i) {
        int c = s[i] - 'a';
        int cur = ++sz;
        len_st[cur] = len_st[last] + 1;
        memset(nxt[cur], 0, sizeof(nxt[cur]));

        int p = last;
        while (p && !nxt[p][c]) {
            nxt[p][c] = cur;
            p = link_st[p];
        }

        if (!p) {
            link_st[cur] = 1;
        } else {
            int q = nxt[p][c];
            if (len_st[p] + 1 == len_st[q]) {
                link_st[cur] = q;
            } else {
                /* Split equivalence class q into clone and q */
                int clone = ++sz;
                len_st[clone] = len_st[p] + 1;
                memcpy(nxt[clone], nxt[q], sizeof(nxt[q]));
                link_st[clone] = link_st[q];
                while (p && nxt[p][c] == q) {
                    nxt[p][c] = clone;
                    p = link_st[p];
                }
                link_st[q] = link_st[cur] = clone;
            }
        }
        last = cur;

        /*
         * State link_st[cur] represents the longest suffix of s[0..i]
         * with |endpos| >= 2 (i.e., occurring at index i and at least once prior).
         */
        int l = len_st[link_st[cur]];
        if (l > max_len) {
            max_len = l;
            best_end = i;
        }
    }

    /* Extract the longest duplicate substring into a null-terminated buffer */
    char* res = (char*)malloc(max_len + 1);
    if (max_len > 0) {
        memcpy(res, s + best_end - max_len + 1, max_len);
    }
    res[max_len] = '\0';
    return res;
}

class Solution {
    /*
     * Architectural Constants & Static Arena Allocation:
     * 1. For N <= 30,000, the Suffix Automaton contains at most 2N - 1 = 59,999 states.
     *    Because 59,999 < 65,535, all state IDs, suffix links, and lengths fit inside
     *    Java's unsigned 16-bit primitive 'char' type, halving cache footprint.
     * 2. Row stride is padded from 26 to 32 (1 << 5) so each state row occupies
     *    32 * 2 bytes = 64 bytes (exact width of one hardware L1d cache line)
     *    and enables single-cycle bitwise indexing: (p << 5) | c.
     */
    private static final int MAX_STATES = 60005;
    private static final char[] nxt = new char[MAX_STATES << 5];
    private static final char[] linkSt = new char[MAX_STATES];
    private static final char[] lenSt = new char[MAX_STATES];
    private static final char[] ZERO_ROW = new char[26];
    public String longestDupSubstring(String s) {
        final int n = s.length();
        int sz = 1, last = 1;
        lenSt[1] = 0;
        linkSt[1] = 0;
        System.arraycopy(ZERO_ROW, 0, nxt, 32, 26);
        int maxLen = 0, bestEnd = 0;
        for (int i = 0; i < n; ++i) {
            final int c = s.charAt(i) - 'a';
            final int cur = ++sz;
            lenSt[cur] = (char) (i + 1);
            System.arraycopy(ZERO_ROW, 0, nxt, cur << 5, 26);
            int p = last;
            while (p != 0 && nxt[(p << 5) | c] == 0) {
                nxt[(p << 5) | c] = (char) cur;
                p = linkSt[p];
            }
            if (p == 0) {
                linkSt[cur] = 1;
            } else {
                final int pIdx = (p << 5) | c;
                final int q = nxt[pIdx];
                final int lp = lenSt[p] + 1;
                if (lp == lenSt[q]) {
                    linkSt[cur] = (char) q;
                } else {
                    final int clone = ++sz;
                    lenSt[clone] = (char) lp;
                    System.arraycopy(nxt, q << 5, nxt, clone << 5, 26);
                    linkSt[clone] = linkSt[q];
                    while (p != 0 && nxt[(p << 5) | c] == q) {
                        nxt[(p << 5) | c] = (char) clone;
                        p = linkSt[p];
                    }
                    linkSt[q] = linkSt[cur] = (char) clone;
                }
                /*
                 * Suffix Link Length Invariant:
                 * Whenever p != 0, lenSt[linkSt[cur]] is strictly equal to lp = lenSt[p] + 1
                 * across both the direct-link and state-cloning branches, eliminating two
                 * dependent memory loads at the end of each character extension.
                 */
                if (lp > maxLen) {
                    maxLen = lp;
                    bestEnd = i;
                }
            }
